def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 4:
        return 'C'
    if n == 99:
        return 'D'
    def opp(i):
        return history[i][1]
    def me(i):
        return history[i][0]
    last_opp = opp(n - 1)
    if n >= 4:
        if opp(n - 2) == 'D' and opp(n - 3) == 'D' and opp(n - 4) == 'D':
            return 'D'
    if n >= 3:
        if last_opp == 'D' and opp(n - 2) == 'D':
            if rng.random() < 0.85:
                return 'D'
    if n >= 2:
        if last_opp == 'D' and opp(n - 2) == 'C':
            return 'C'
    c_opp = 0
    d_opp = 0
    c_me = 0
    d_me = 0
    for i in range(n):
        if opp(i) == 'C':
            c_opp += 1
        else:
            d_opp += 1
        if me(i) == 'C':
            c_me += 1
        else:
            d_me += 1
    if n >= 10:
        opp_rate = c_opp / n
        me_rate = c_me / n
        if opp_rate > 0.85:
            if me_rate < 0.6:
                return 'C'
            if rng.random() < 0.7:
                return 'C'
        if opp_rate < 0.15:
            return 'D'
        if opp_rate > 0.6 and me_rate > 0.6:
            if rng.random() < 0.85:
                return 'C'
        if opp_rate < 0.4:
            if rng.random() < 0.6:
                return 'D'
            return 'C'
    return 'C'

